import{z as n,x as B,o as E,c,q as l,j as d,D as t,d as e,s,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"类型类与字典传递","description":"","frontmatter":{"title":"类型类与字典传递","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/typeclass-dictionary.md","filePath":"cs/typeclass-dictionary.md","lastUpdated":1791063341000}'),p={name:"cs/typeclass-dictionary.md"};function A(h,a,m,D,C,q){const r=B("Mermaid");return E(),c("div",null,[a[2]||(a[2]=l('<h1 id="类型类与字典传递" tabindex="-1">类型类与字典传递 <a class="header-anchor" href="#类型类与字典传递" aria-label="Permalink to &quot;类型类与字典传递&quot;">​</a></h1><div class="epigraph"><p>类型类是谓词：$\\mathrm{Eq}\\,a$ 表示 $a$ 有一份相等字典。编译器把隐式字典当额外参数传，而不是靠名义继承。</p><footer>—— 据 Wadler and Blott, How to Make Ad-hoc Polymorphism Less Ad-hoc, 1989；Peyton Jones 等 GHC 实现笔记；Pierce TAPL 对照整理</footer></div><p>上一课<a href="/cs/generics-monomorphization">泛型实现</a>把 \\(\\forall\\) 降到代码。缺口是<strong>特设重载</strong>：\\(==\\) 在 <code>int</code> 与 <code>[a]</code> 上不同，却要同一套静态决议。类型类（Haskell）/ trait（Rust）给出约束；实现上常是<strong>字典传递</strong>：记录一组函数指针。本课钉决议与字典，不重写子类型的 \\(\\lt :\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HM 不能表示 <code>==</code> 的无限族。类型类：<code>Eq a =&gt; a -&gt; a -&gt; Bool</code>。实例解析：根据调用处的 \\(a\\) 找唯一实例（或重叠规则）。缺口是<strong>隐式参数从哪来</strong>，不是再写 W 的 let。</p><p>字典：<code>Eq a</code> 的值是 <code>{eq: a→a→Bool, ...}</code>。递归实例（<code>Eq a =&gt; Eq [a]</code>）对应字典的延迟/递归构造。单态化语言可把字典调用特化成直接调用。</p><p><span class="marginnote">「字典传递」就是把 <code>Eq a</code> 当成一个装满函数指针的记录（比如 <code>{eq: a→a→Bool}</code>），编译器把它作为看不见的额外参数，塞进每个用到 <code>==</code> 的函数签名里。</span></p><h3 id="字典不是-vtable-的全部-oop" tabindex="-1">字典不是 vtable 的全部 OOP <a class="header-anchor" href="#字典不是-vtable-的全部-oop" aria-label="Permalink to &quot;字典不是 vtable 的全部 OOP&quot;">​</a></h3><p>vtable 绑在对象头，方法以 <code>self</code> 为隐式；字典常绑在调用处的类型，不必有对象头。二者都是间接调用，身份不同。后课虚表再对照。</p><p><span class="marginnote">Wadler–Blott 1989。GHC 把类约束编译为函数参数。Rust trait 对象是字典+数据的胖指针，静态 trait 则单态化。本课以字典传递为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>类型检查：收集约束，用实例库求解（后向链）。失败：歧义（<code>show . read</code>）或缺实例。代码生成：给每个约束一个参数；调用 <code>eq</code> 变成 <code>d.eq</code>。</p>',12)),(E(),d(i,null,{default:t(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CST%5B%22%E7%B1%BB%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SOL%5B%22%E5%AE%9E%E4%BE%8B%E6%B1%82%E8%A7%A3%22%5D%0A%20%20SOL%20--%3E%20DICT%5B%22%E5%AD%97%E5%85%B8%E5%80%BC%22%5D%0A%20%20DICT%20--%3E%20CALL%5B%22%E9%97%B4%E6%8E%A5%E6%88%96%E7%89%B9%E5%8C%96%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,[e("与"),o("a",{href:"/cs/let-polymorphism"},"值限制"),e("：多态约束的 let 仍要推广规则；字典本身是值。")],-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"连贯性回答的是「特化优化为什么不会偷偷改语义」：",-1)),(E(),d(i,null,{default:t(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQI%5B%22Eq%20Int%20%E7%9A%84%E5%AE%9E%E4%BE%8B%22%5D%20--%3E%20Q%7B%22%E5%90%8C%E4%B8%80%E7%B1%BB%E5%9E%8B%E5%90%8C%E4%B8%80%E7%B1%BB%EF%BC%8C%E5%87%A0%E4%BB%BD%E5%AD%97%E5%85%B8%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E5%85%81%E8%AE%B8%E4%B8%80%E4%BB%BD%22%7C%20COH%5B%22%E8%BF%9E%E8%B4%AF%E6%80%A7%E6%88%90%E7%AB%8B%22%5D%0A%20%20COH%20--%3E%20SPEC%5B%22%E7%89%B9%E5%8C%96%2F%E5%86%85%E8%81%94%E6%8D%A2%E6%9D%A5%E7%9A%84%E8%BF%98%E6%98%AF%E9%82%A3%E4%BB%BD%20eq%22%5D%0A%20%20SPEC%20--%3E%20SAME%5B%22%E8%A1%8C%E4%B8%BA%E4%B8%8D%E5%8F%98%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%A4%E4%BB%BD%E4%B8%8D%E5%90%8C%E5%AE%9E%E7%8E%B0%22%7C%20BAD%5B%22%E4%BC%98%E5%8C%96%E5%8F%AF%E8%83%BD%E6%8D%A2%E6%8E%89%E8%B0%83%E7%94%A8%E7%9B%AE%E6%A0%87%22%5D%0A%20%20BAD%20--%3E%20DIFF%5B%22%E5%90%8C%E4%B8%80%E6%AF%94%E8%BE%83%E7%BB%93%E6%9E%9C%E4%B8%8D%E5%90%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>重叠实例使求解不确定，语言或禁或优先级。孤儿实例破坏模块化，工程上限制。连贯性（coherence）：同一类型同一类最多一份字典，否则优化（特化）会改变哪份 <code>eq</code>。</p><p>不要用类型类模拟全部依赖注入框架；它是编译期决议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 higher-kinded 的全部种类。后课默认：特设多态 = 约束 + 字典或特化。下一课 ADT 与模式匹配编译——数据侧，不再是隐式参数。</p><p>也不把 C++ ADL 与类型类等同，只点名都是重载决议家族。</p><p><span class="marginnote">常见误区：初学者容易把「孤儿实例」当成便利——在自己的模块里给别人的类型加实现多方便。问题在于两个模块各加一份后，同一个调用可能解析到不同字典，库作者无法保证语义一致。</span></p><p><span class="marginnote">直觉类比：连贯性像「全国只发一种版式的驾照」——同一类型同一类只允许一份实现，优化器随便内联、特化，都不会把 A 地的 <code>eq</code> 换成 B 地的 <code>eq</code>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型类约束在编译期求解，运行期常成字典参数。</li><li>与对象虚表：间接调用类似，分派键是类型不是对象头。</li><li>连贯性保证特化不改语义。</li><li>出处：Wadler and Blott, 1989；GHC 笔记；Pierce TAPL。</li></ul>',9))])}const _=n(p,[["render",A]]);export{f as __pageData,_ as default};
